using System.Linq.Expressions;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using UAF.Application.Common.Abstractions;
using UAF.Domain.Common;
using UAF.Domain.Entities;
using UAF.Infrastructure.Identity;
namespace UAF.Infrastructure.Persistence;
public sealed class UafDbContext:IdentityDbContext<ApplicationUser,IdentityRole<Guid>,Guid>,IUnitOfWork{
 public UafDbContext(DbContextOptions<UafDbContext> options):base(options){}
 public DbSet<University> Universities=>Set<University>();public DbSet<Campus> Campuses=>Set<Campus>();public DbSet<Faculty> Faculties=>Set<Faculty>();public DbSet<Department> Departments=>Set<Department>();public DbSet<AcademicProgram> AcademicPrograms=>Set<AcademicProgram>();public DbSet<AcademicSession> AcademicSessions=>Set<AcademicSession>();public DbSet<Student> Students=>Set<Student>();public DbSet<AdmissionApplication> AdmissionApplications=>Set<AdmissionApplication>();public DbSet<AdmissionDocument> AdmissionDocuments=>Set<AdmissionDocument>();public DbSet<AdmissionDocumentRequirement> AdmissionDocumentRequirements=>Set<AdmissionDocumentRequirement>();public DbSet<AdmissionDecisionAudit> AdmissionDecisionAudits=>Set<AdmissionDecisionAudit>();public DbSet<RegistrationNumberSeries> RegistrationNumberSeries=>Set<RegistrationNumberSeries>();public DbSet<Course> Courses=>Set<Course>();public DbSet<CourseOffering> CourseOfferings=>Set<CourseOffering>();public DbSet<CourseEnrollment> CourseEnrollments=>Set<CourseEnrollment>();public DbSet<FeeHead> FeeHeads=>Set<FeeHead>();public DbSet<FeeStructure> FeeStructures=>Set<FeeStructure>();public DbSet<FeeStructureItem> FeeStructureItems=>Set<FeeStructureItem>();public DbSet<StudentFeeAccount> StudentFeeAccounts=>Set<StudentFeeAccount>();public DbSet<FeeChallan> FeeChallans=>Set<FeeChallan>();public DbSet<FeeChallanLine> FeeChallanLines=>Set<FeeChallanLine>();public DbSet<FeePayment> FeePayments=>Set<FeePayment>();public DbSet<Employee> Employees=>Set<Employee>();public DbSet<TeacherProfile> TeacherProfiles=>Set<TeacherProfile>();public DbSet<AttendanceSession> AttendanceSessions=>Set<AttendanceSession>();public DbSet<StudentAttendance> StudentAttendances=>Set<StudentAttendance>();public DbSet<AttendanceChangeAudit> AttendanceChangeAudits=>Set<AttendanceChangeAudit>();public DbSet<AttendancePolicy> AttendancePolicies=>Set<AttendancePolicy>();public DbSet<Examination> Examinations=>Set<Examination>();public DbSet<ExaminationResult> ExaminationResults=>Set<ExaminationResult>();public DbSet<ExaminationResultAudit> ExaminationResultAudits=>Set<ExaminationResultAudit>();public DbSet<GradeScale> GradeScales=>Set<GradeScale>();public DbSet<GradeScaleBand> GradeScaleBands=>Set<GradeScaleBand>();public DbSet<StudentCourseGrade> StudentCourseGrades=>Set<StudentCourseGrade>();public DbSet<GradeAppeal> GradeAppeals=>Set<GradeAppeal>();public DbSet<GradeAppealAudit> GradeAppealAudits=>Set<GradeAppealAudit>();public DbSet<GradeRevisionRequest> GradeRevisionRequests=>Set<GradeRevisionRequest>();public DbSet<GradeRevision> GradeRevisions=>Set<GradeRevision>();public DbSet<GradeRevisionAudit> GradeRevisionAudits=>Set<GradeRevisionAudit>();public DbSet<AcademicTranscript> AcademicTranscripts=>Set<AcademicTranscript>();public DbSet<RefreshToken> RefreshTokens=>Set<RefreshToken>();public DbSet<IdempotencyRecord> IdempotencyRecords=>Set<IdempotencyRecord>();public DbSet<TeachingRoom> TeachingRooms=>Set<TeachingRoom>();public DbSet<TimetableEntry> TimetableEntries=>Set<TimetableEntry>();
 public DbSet<Notification> Notifications=>Set<Notification>();public DbSet<WorkflowInstance> WorkflowInstances=>Set<WorkflowInstance>();public DbSet<WorkflowApprovalStep> WorkflowApprovalSteps=>Set<WorkflowApprovalStep>();public DbSet<WorkflowHistory> WorkflowHistory=>Set<WorkflowHistory>();public DbSet<AuditTrailEntry> AuditTrailEntries=>Set<AuditTrailEntry>();
 protected override void OnModelCreating(ModelBuilder modelBuilder){base.OnModelCreating(modelBuilder);modelBuilder.ApplyConfigurationsFromAssembly(typeof(UafDbContext).Assembly);foreach(var entityType in modelBuilder.Model.GetEntityTypes().Where(t=>t.ClrType is not null&&typeof(Entity).IsAssignableFrom(t.ClrType)&&!t.ClrType.IsAbstract)){var p=Expression.Parameter(entityType.ClrType,"entity");var deleted=Expression.Property(p,nameof(Entity.IsDeleted));modelBuilder.Entity(entityType.ClrType).HasQueryFilter(Expression.Lambda(Expression.Not(deleted),p));modelBuilder.Entity(entityType.ClrType).Property(nameof(Entity.RowVersion)).IsRowVersion();}modelBuilder.Entity<ApplicationUser>(e=>{e.Property(x=>x.FullName).HasMaxLength(150).IsRequired();e.Property(x=>x.IsActive).IsRequired();});}
 public override int SaveChanges(){ApplyAuditInformation();return base.SaveChanges();}
 public override Task<int> SaveChangesAsync(CancellationToken ct=default){ApplyAuditInformation();return base.SaveChangesAsync(ct);}
 private void ApplyAuditInformation(){
 if(ChangeTracker.Entries<AuditTrailEntry>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Central audit trail records are append-only.");
 if(ChangeTracker.Entries<WorkflowHistory>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Workflow history records are append-only.");
 if(ChangeTracker.Entries<AdmissionDecisionAudit>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Admission decision audit records are append-only.");
 if(ChangeTracker.Entries<AttendanceChangeAudit>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Attendance change audit records are append-only.");
 if(ChangeTracker.Entries<ExaminationResultAudit>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Examination result audit records are append-only.");
 if(ChangeTracker.Entries<GradeAppealAudit>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Grade appeal audit records are append-only.");
 if(ChangeTracker.Entries<GradeRevisionRequest>().Any(e=>e.State==EntityState.Deleted))throw new InvalidOperationException("Grade revision requests cannot be deleted.");
 if(ChangeTracker.Entries<GradeRevisionAudit>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Grade revision audit records are append-only.");
 if(ChangeTracker.Entries<GradeRevision>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Grade revision snapshots are immutable.");
 if(ChangeTracker.Entries<AcademicTranscript>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Issued transcripts are immutable.");
 if(ChangeTracker.Entries<StudentCourseGrade>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Finalized grades are immutable; use grade revision.");
 if(ChangeTracker.Entries<GradeScaleBand>().Any(e=>e.State is EntityState.Modified or EntityState.Deleted))throw new InvalidOperationException("Grade scale bands are immutable.");
 if(ChangeTracker.Entries<GradeScale>().Any(e=>e.State==EntityState.Deleted||(e.State==EntityState.Modified&&e.OriginalValues.GetValue<bool>(nameof(GradeScale.IsPublished)))))throw new InvalidOperationException("Published grading scales cannot be modified or deleted.");
 foreach(var e in ChangeTracker.Entries<Entity>().Where(e=>e.State==EntityState.Deleted)){e.Entity.SoftDelete();e.State=EntityState.Modified;}
 var now=DateTimeOffset.UtcNow;foreach(var e in ChangeTracker.Entries<AuditableEntity>()){if(e.State==EntityState.Added)e.Property(x=>x.CreatedAtUtc).CurrentValue=now;if(e.State==EntityState.Modified){e.Property(x=>x.CreatedAtUtc).IsModified=false;e.Property(x=>x.UpdatedAtUtc).CurrentValue=now;}}
 }
}
